mention mtgui

app = mtgui.window("Colors", 360, 200)
shown = app:text "Pick a color"
choices = app:row
choices:button("Red", pick_red, "outline")
choices:button("Green", pick_green, "outline")
choices:button("Blue", pick_blue, "outline")

func choose(name, color_name):
    shown:set name
    shown:color color_name

func pick_red(): choose("Red", "red")
func pick_green(): choose("Green", "green")
func pick_blue(): choose("Blue", "blue")

mention mtgui

app = mtgui.window("Name tag", 360, 200)
tag = app:text "No name yet"
app:button("Set name", set_name, "primary")

func set_name():
    typed_name = app:ask "What is your name?"
    if typed_name:trim() is "":
        tag:set "No name given"
    else:
        tag:set "Hi, " + typed_name + "!"

mention tgui

app = tgui.window("Rocket", 320, 200)
left = 10
big = app:heading "10"
app:every(1, tick)

func tick():
    if left <= 0:
        return
    left -= 1
    if left is 0:
        big:set "Liftoff!"
    else:
        big:set text(left)

mention mtgui

app = mtgui.window("Settings", 360, 260)
app:heading "Settings"
light = app:toggle("Light mode", false)
tips = app:checkbox("Show tips", false)
tip_text = app:small "Tip: save often!"
tip_text:hide
light:change light_flipped
tips:change tips_flipped

func light_flipped(on):
    if on:
        app:theme "light"
    else:
        app:theme "dark"

func tips_flipped(on):
    if on:
        tip_text:show
    else:
        tip_text:hide
